1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	
60		// silences keyed by silence id; same lock so alert evaluation reads
61		// metrics, rules and silences from one consistent snapshot.
62		silences map[string]*silence
63	}
64	
65	func newMetricStore() *metricStore {
66		return &metricStore{
67			series:   make(map[string]*series),
68			rules:    make(map[string]*alertRule),
69			silences: make(map[string]*silence),
70		}
71	}
72	
73	// validatedSample is a sample that passed all format and value checks.
74	type validatedSample struct {
75		key     string
76		name    string
77		typ     string
78		labels  map[string]string
79		value   float64
80		buckets []float64 // non-nil for histograms
81	}
82	
83	// checkAndApply validates the batch against the current state (and against
84	// itself) and then commits it in array order. A false result signals a type or
85	// bucket-boundary conflict; in that case no state is mutated.
86	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
87		s.mu.Lock()
88		defer s.mu.Unlock()
89	
90		// First pass: conflict detection against committed state and earlier
91		// samples in the same batch.
92		resolved := make(map[string]*series, len(batch))
93		for _, sm := range batch {
94			existing, ok := s.series[sm.key]
95			if !ok {
96				if shadow, seen := resolved[sm.key]; seen {
97					existing, ok = shadow, true
98				}
99			}
100			if ok {
101				if existing.typ != sm.typ {
102					return false
103				}
104				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
105					return false
106				}
107				resolved[sm.key] = existing
108				continue
109			}
110			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
111		}
112	
113		// Second pass: commit in order.
114		for _, sm := range batch {
115			cur, ok := s.series[sm.key]
116			if !ok {
117				cur = &series{
118					name:         sm.name,
119					typ:          sm.typ,
120					labels:       sm.labels,
121					bucketBounds: append([]float64(nil), sm.buckets...),
122				}
123				if sm.typ == "histogram" {
124					cur.bucketCounts = make([]int64, len(sm.buckets))
125				}
126				s.series[sm.key] = cur
127			}
128			switch sm.typ {
129			case "counter":
130				cur.value += sm.value
131			case "gauge":
132				cur.value = sm.value
133			case "histogram":
134				cur.count++
135				cur.sum += sm.value
136				for i, bound := range cur.bucketBounds {
137					if sm.value <= bound {
138						cur.bucketCounts[i]++
139					}
140				}
141			}
142		}
143		return true
144	}
145	
146	type seriesOutput struct {
147		Name    string            `json:"name"`
148		Type    string            `json:"type"`
149		Labels  map[string]string `json:"labels"`
150		Value   *float64          `json:"value,omitempty"`
151		Count   *int64            `json:"count,omitempty"`
152		Sum     *float64          `json:"sum,omitempty"`
153		Buckets []bucketOutput    `json:"buckets,omitempty"`
154	}
155	
156	type bucketOutput struct {
157		LE    float64 `json:"le"`
158		Count int64   `json:"count"`
159	}
160	
161	// query returns matching series as ready-to-encode outputs. A series matches
162	// when its name equals name exactly and it contains every selector label.
163	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
164		s.mu.RLock()
165		defer s.mu.RUnlock()
166	
167		out := make([]seriesOutput, 0)
168		for _, cur := range s.series {
169			if cur.name != name {
170				continue
171			}
172			matched := true
173			for k, v := range selector {
174				got, ok := cur.labels[k]
175				if !ok || got != v {
176					matched = false
177					break
178				}
179			}
180			if !matched {
181				continue
182			}
183			item := seriesOutput{
184				Name:   cur.name,
185				Type:   cur.typ,
186				Labels: copyLabels(cur.labels),
187			}
188			switch cur.typ {
189			case "counter", "gauge":
190				v := cur.value
191				item.Value = &v
192			case "histogram":
193				c, sum := cur.count, cur.sum
194				item.Count = &c
195				item.Sum = &sum
196				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
197				for i, bound := range cur.bucketBounds {
198					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
199				}
200			}
201			out = append(out, item)
202		}
203	
204		sort.Slice(out, func(i, j int) bool {
205			return compareLabels(out[i].Labels, out[j].Labels) < 0
206		})
207		return out
208	}
209	
210	// compareLabels imposes a normalized lexicographic order on full label sets:
211	// keys are sorted, then (key, value) pairs are compared element-wise, and a
212	// shorter pair list sorts first when it is a prefix of a longer one.
213	func compareLabels(a, b map[string]string) int {
214		ka := sortedKeys(a)
215		kb := sortedKeys(b)
216		n := len(ka)
217		if len(kb) < n {
218			n = len(kb)
219		}
220		for i := 0; i < n; i++ {
221			if ka[i] != kb[i] {
222				return strings.Compare(ka[i], kb[i])
223			}
224			if a[ka[i]] != b[kb[i]] {
225				return strings.Compare(a[ka[i]], b[kb[i]])
226			}
227		}
228		switch {
229		case len(ka) < len(kb):
230			return -1
231		case len(ka) > len(kb):
232			return 1
233		default:
234			return 0
235		}
236	}
237	
238	func sortedKeys(m map[string]string) []string {
239		keys := make([]string, 0, len(m))
240		for k := range m {
241			keys = append(keys, k)
242		}
243		sort.Strings(keys)
244		return keys
245	}
246	
247	func copyLabels(in map[string]string) map[string]string {
248		out := make(map[string]string, len(in))
249		for k, v := range in {
250			out[k] = v
251		}
252		return out
253	}
254	
255	// seriesKey builds a collision-free identity from name + unordered labels.
256	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
257	// so length-prefixed values remove any ambiguity from arbitrary label values.
258	func seriesKey(name string, labels map[string]string) string {
259		var b strings.Builder
260		b.WriteString(name)
261		for _, k := range sortedKeys(labels) {
262			b.WriteByte(0)
263			b.WriteString(k)
264			b.WriteByte(0)
265			v := labels[k]
266			b.WriteString(strconv.Itoa(len(v)))
267			b.WriteByte(0)
268			b.WriteString(v)
269		}
270		return b.String()
271	}
272	
273	func equalBuckets(a, b []float64) bool {
274		if len(a) != len(b) {
275			return false
276		}
277		for i := range a {
278			if a[i] != b[i] {
279				return false
280			}
281		}
282		return true
283	}
284	
285	// Handler returns the HTTP surface served by SignalWatch.
286	func Handler() http.Handler {
287		mux := http.NewServeMux()
288		store := newMetricStore()
289	
290		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
291			if r.Method != http.MethodGet {
292				w.Header().Set("Allow", http.MethodGet)
293				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
294				return
295			}
296			w.Header().Set("Content-Type", "application/json; charset=utf-8")
297			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
298		})
299	
300		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
301			switch r.Method {
302			case http.MethodGet:
303				handleMetricsGet(w, r, store)
304			case http.MethodPost:
305				handleMetricsPost(w, r, store)
306			default:
307				w.Header().Set("Allow", "GET, POST")
308				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
309			}
310		})
311	
312		registerAlertHandlers(mux, store)
313		registerSilenceHandlers(mux, store)
314	
315		return mux
316	}
317	
318	func handleMetricsPost(w http.ResponseWriter, r *http.Request, store *metricStore) {
319		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
320		if err != nil || mediaType != "application/json" {
321			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
322			return
323		}
324	
325		body, err := io.ReadAll(r.Body)
326		if err != nil {
327			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
328			return
329		}
330	
331		batch, ok := decodeMetricsBatch(body)
332		if !ok {
333			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
334			return
335		}
336	
337		if !store.checkAndApply(batch) {
338			writeAPIError(w, "metric_conflict", http.StatusConflict)
339			return
340		}
341	
342		w.Header().Set("Content-Type", "application/json; charset=utf-8")
343		w.WriteHeader(http.StatusAccepted)
344		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
345	}
346	
347	type metricsEnvelope struct {
348		Samples *[]json.RawMessage `json:"samples"`
349	}
350	
351	type rawSample struct {
352		Name    *string            `json:"name"`
353		Type    *string            `json:"type"`
354		Labels  *map[string]string `json:"labels"`
355		Value   *float64           `json:"value"`
356		Buckets *[]float64         `json:"buckets"`
357	}
358	
359	// decodeMetricsBatch performs every format and value check. It never returns a
360	// partially validated batch.
361	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
362		var env metricsEnvelope
363		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
364			return nil, false
365		}
366	
367		batch := make([]validatedSample, 0, len(*env.Samples))
368		for _, raw := range *env.Samples {
369			var sm rawSample
370			if !strictDecode(raw, &sm) {
371				return nil, false
372			}
373			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
374				return nil, false
375			}
376			name, typ := *sm.Name, *sm.Type
377			if !identPattern.MatchString(name) {
378				return nil, false
379			}
380			if typ != "counter" && typ != "gauge" && typ != "histogram" {
381				return nil, false
382			}
383			labels := *sm.Labels
384			if labels == nil {
385				return nil, false // explicit null labels
386			}
387			for k := range labels {
388				if !identPattern.MatchString(k) {
389					return nil, false
390				}
391			}
392			value := *sm.Value
393			if math.IsNaN(value) || math.IsInf(value, 0) {
394				return nil, false // encoding/json already rejects NaN/Inf tokens
395			}
396			if typ == "counter" && value < 0 {
397				return nil, false
398			}
399	
400			var buckets []float64
401			if typ == "histogram" {
402				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
403					return nil, false
404				}
405				buckets = append([]float64(nil), (*sm.Buckets)...)
406			} else if sm.Buckets != nil {
407				return nil, false // buckets only valid on histograms
408			}
409	
410			batch = append(batch, validatedSample{
411				key:     seriesKey(name, labels),
412				name:    name,
413				typ:     typ,
414				labels:  copyLabels(labels),
415				value:   value,
416				buckets: buckets,
417			})
418		}
419		return batch, true
420	}
421	
422	func validBuckets(buckets []float64) bool {
423		if len(buckets) == 0 {
424			return false
425		}
426		prev := math.Inf(-1)
427		for _, b := range buckets {
428			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
429				return false
430			}
431			prev = b
432		}
433		return true
434	}
435	
436	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
437	// values and non-object payloads for struct targets.
438	func strictDecode(data []byte, target any) bool {
439		dec := json.NewDecoder(bytes.NewReader(data))
440		dec.DisallowUnknownFields()
441		if err := dec.Decode(target); err != nil {
442			return false
443		}
444		var extra json.RawMessage
445		if err := dec.Decode(&extra); err != io.EOF {
446			return false
447		}
448		return true
449	}
450	
451	func handleMetricsGet(w http.ResponseWriter, r *http.Request, store *metricStore) {
452		values, err := url.ParseQuery(r.URL.RawQuery)
453		if err != nil {
454			writeAPIError(w, "invalid_query", http.StatusBadRequest)
455			return
456		}
457	
458		names := values["name"]
459		if len(names) == 0 || !identPattern.MatchString(names[0]) {
460			writeAPIError(w, "invalid_query", http.StatusBadRequest)
461			return
462		}
463	
464		selector := make(map[string]string)
465		for key, vals := range values {
466			if !strings.HasPrefix(key, "label.") {
467				continue
468			}
469			labelKey := strings.TrimPrefix(key, "label.")
470			if !identPattern.MatchString(labelKey) {
471				writeAPIError(w, "invalid_query", http.StatusBadRequest)
472				return
473			}
474			for _, v := range vals[1:] {
475				if v != vals[0] {
476					writeAPIError(w, "invalid_query", http.StatusBadRequest)
477					return
478				}
479			}
480			selector[labelKey] = vals[0]
481		}
482	
483		seriesList := store.query(names[0], selector)
484		w.Header().Set("Content-Type", "application/json; charset=utf-8")
485		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
486	}
487	
488	func writeAPIError(w http.ResponseWriter, code string, status int) {
489		w.Header().Set("Content-Type", "application/json; charset=utf-8")
490		w.WriteHeader(status)
491		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
492	}
493

