package server

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func inhibitRequest(t *testing.T, h http.Handler, method, id, body, contentType string) *httptest.ResponseRecorder {
	t.Helper()
	target := inhibitRulesPath
	if id != "" {
		target += "/" + id
	}
